            d["Iconos de los botones:"] = "Icônes des boutons :";
            d["El menú puede accionar tu programa de capturas (GameHQ, NVIDIA App, Steam, Xbox Game Bar...) enviándole su atajo de teclado. Elige uno para rellenar los atajos habituales y corrígelos si los has cambiado en ese programa. Los que dejes vacíos no aparecen en el menú. Formato: Ctrl+Shift+S, Alt+F1, Win+Alt+PrtScn..."] = "Le menu peut piloter votre logiciel de capture (GameHQ, NVIDIA App, Steam, Xbox Game Bar...) en lui envoyant son raccourci clavier. Choisissez-en un pour remplir les raccourcis habituels et corrigez-les si vous les avez modifiés dans ce programme. Ceux que vous laissez vides n'apparaissent pas dans le menu. Format : Ctrl+Shift+S, Alt+F1, Win+Alt+PrtScn...";
            d["Programa:"] = "Programme :";
